/**
 * Writer target tree (foundry-build-0019; ia-target writer.md 2): three L0 groups in owner order, Voice, Prose and
 * Copy. Voice and Prose are authored by hand; Copy is generated by `src/derive` from the Designer catalog. The old
 * five-layer files (lexicon, strings, patterns, passages, narratives) stay as storage; every old id that is not kept
 * here has one row in `src/catalog/retired.json` naming its fate and target.
 */
import { readFileSync } from "node:fs";

export const WRITER_GROUPS = ["voice", "prose", "copy"] as const;
export type WriterGroup = (typeof WRITER_GROUPS)[number];
export const WRITER_MARKS = ["starter", "other-live", "parked"] as const;
export type WriterMark = (typeof WRITER_MARKS)[number];

/** A named input. Director refs always carry the `mustContain` key they read (foundry-audit-0016). */
export interface WriterRef { to: string; key?: string; rel?: string }
export interface GroupSlot {
  id: string;
  kind: "voice" | "prose" | "copy";
  mark: WriterMark;
  inputs: WriterRef[];
  contract: Record<string, any>;
  new?: boolean;
}
/** A Copy leaf whose Designer unit declares no copy fields yet: placed and frozen, not a slot. */
export interface AwaitingLeaf { id: string; unit: string; mark: WriterMark; reason: string }
export interface GroupL2 { id: string; label: string; leaves: string[] }
export interface GroupL1 { id: string; label: string; children: GroupL2[] }
export interface GroupTree {
  schema: "clossys.writer-ia/1";
  group: WriterGroup;
  label: string;
  nodes: GroupL1[];
  slots: GroupSlot[];
  awaiting?: AwaitingLeaf[];
}
export interface WriterTreeFinding { code: string; group: string; message: string }
export interface RetiredRow { id: string; fate: string; target: string }

export const LEAF_FORM: Readonly<Record<WriterGroup, RegExp>> = {
  voice: /^lexicon\.[a-z0-9]+(?:-[a-z0-9]+)*$/,
  prose: /^narratives\.[a-z0-9]+(?:-[a-z0-9]+)*$/,
  copy: /^(?:components|sections|frames|assets)\.[a-z0-9]+(?:-[a-z0-9]+)*\.copy$/,
};
const GROUP_LABELS: Readonly<Record<WriterGroup, string>> = { voice: "Voice", prose: "Prose", copy: "Copy" };
const OLD_LAYERS = ["lexicon", "strings", "patterns", "passages", "narratives"] as const;
export const RETIRED_FATES = ["copy", "prose", "purpose-shape", "field-role", "intl-code", "director-field", "dropped"] as const;

const packageFile = (path: string): URL => new URL(`../../../${path}`, import.meta.url);
const readJson = (path: string): any => JSON.parse(readFileSync(packageFile(path), "utf8"));

export function loadWriterTrees(): GroupTree[] {
  return WRITER_GROUPS.map(group => {
    const tree = readJson(`src/catalog/ia/${group}.json`) as GroupTree;
    if (!tree || tree.group !== group || !Array.isArray(tree.nodes) || !Array.isArray(tree.slots)) throw new Error(`Writer IA: invalid ${group}.json shape`);
    return tree;
  });
}

export function loadWriterRetired(): RetiredRow[] {
  const rows = readJson("src/catalog/retired.json");
  if (!Array.isArray(rows)) throw new Error("Writer IA: retired.json must be an array");
  return rows as RetiredRow[];
}

/** Every leaf id of the old five-layer tree (137 at the recut). */
export function oldWriterLeafIds(): string[] {
  return OLD_LAYERS.flatMap(layer => {
    const placement = readJson(`src/catalog/ia/${layer}.json`) as { nodes: { children: { leaves: string[] }[] }[] };
    return placement.nodes.flatMap(l1 => l1.children.flatMap(l2 => l2.leaves));
  });
}

export const leavesOf = (tree: GroupTree): string[] => tree.nodes.flatMap(l1 => l1.children.flatMap(l2 => l2.leaves));

/** Mark of a placed leaf: the slot's mark, or the awaiting reservation's. */
function markOf(tree: GroupTree, id: string): WriterMark | undefined {
  return tree.slots.find(slot => slot.id === id)?.mark ?? tree.awaiting?.find(leaf => leaf.id === id)?.mark;
}

export interface GroupCount { l1: number; l2: number; l3: number; slots: number; awaiting: number; marks: Record<WriterMark, number> }
export interface WriterCounts { l0: number; l1: number; l2: number; l3: number; byGroup: Record<string, GroupCount> }

export function countWriterTrees(trees: readonly GroupTree[]): WriterCounts {
  const byGroup: Record<string, GroupCount> = {};
  let l1 = 0, l2 = 0, l3 = 0;
  for (const tree of trees) {
    const leaves = leavesOf(tree);
    const marks: Record<WriterMark, number> = { starter: 0, "other-live": 0, parked: 0 };
    for (const id of leaves) { const mark = markOf(tree, id); if (mark) marks[mark] += 1; }
    const count: GroupCount = {
      l1: tree.nodes.length, l2: tree.nodes.reduce((sum, node) => sum + node.children.length, 0), l3: leaves.length,
      slots: tree.slots.length, awaiting: tree.awaiting?.length ?? 0, marks,
    };
    byGroup[tree.group] = count;
    l1 += count.l1; l2 += count.l2; l3 += count.l3;
  }
  return { l0: trees.length, l1, l2, l3, byGroup };
}

/** Placement soundness: id forms, unique placement, every slot placed, no empty node, marks known. */
export function checkWriterTrees(trees: readonly GroupTree[]): WriterTreeFinding[] {
  const findings: WriterTreeFinding[] = [];
  const seen = new Map<string, number>();
  if (trees.map(tree => tree.group).join() !== WRITER_GROUPS.join()) findings.push({ code: "IA", group: "*", message: `IA: groups must be ${WRITER_GROUPS.join(", ")} in order` });
  for (const tree of trees) {
    const fail = (message: string) => { findings.push({ code: "IA", group: tree.group, message }); };
    if (tree.schema !== "clossys.writer-ia/1") fail(`IA: ${tree.group} has schema ${String(tree.schema)}`);
    if (tree.label !== GROUP_LABELS[tree.group]) fail(`IA: ${tree.group} label must be ${GROUP_LABELS[tree.group]}`);
    const form = LEAF_FORM[tree.group];
    const nodeIds = new Set<string>();
    const known = new Set<string>([...tree.slots.map(slot => slot.id), ...(tree.awaiting ?? []).map(leaf => leaf.id)]);
    if (known.size !== tree.slots.length + (tree.awaiting?.length ?? 0)) fail(`IA: ${tree.group} declares a slot or awaiting leaf twice`);
    for (const l1 of tree.nodes) {
      if (!l1.label?.trim() || !l1.id.startsWith(`${tree.group}/`) || nodeIds.has(l1.id)) fail(`IA: invalid L1 ${l1.id}`);
      nodeIds.add(l1.id);
      if (!l1.children?.length) fail(`IA: L1 ${l1.id} is empty`);
      for (const l2 of l1.children ?? []) {
        if (!l2.label?.trim() || !l2.id.startsWith(`${l1.id}/`) || nodeIds.has(l2.id)) fail(`IA: invalid L2 ${l2.id}`);
        nodeIds.add(l2.id);
        if (!l2.leaves?.length) fail(`IA: L2 ${l2.id} is empty`);
        for (const id of l2.leaves ?? []) {
          seen.set(id, (seen.get(id) ?? 0) + 1);
          if (!form.test(id)) fail(`IA: ${id} is not a ${tree.group} leaf id`);
          if (!known.has(id)) fail(`IA: ${id} is placed but is neither a slot nor an awaiting leaf`);
        }
      }
    }
    const placed = new Set(leavesOf(tree));
    for (const id of known) if (!placed.has(id)) fail(`IA: ${id} is not placed`);
    for (const slot of tree.slots) {
      if (slot.kind !== tree.group) fail(`IA: ${slot.id} has kind ${slot.kind}`);
      if (!WRITER_MARKS.includes(slot.mark)) fail(`IA: ${slot.id} has mark ${String(slot.mark)}`);
    }
    for (const leaf of tree.awaiting ?? []) if (!WRITER_MARKS.includes(leaf.mark) || !leaf.reason?.trim()) fail(`IA: awaiting ${leaf.id} needs a mark and a reason`);
  }
  for (const [id, count] of seen) if (count !== 1) findings.push({ code: "IA", group: "*", message: `IA: ${id} is placed ${count} times` });
  return findings;
}

const DIRECTOR_FIELD = /^[a-z]+\.[a-z-]+\.[a-z-]+(?::[A-Z][A-Za-z-]*)?$/;

/** Every old id that is not kept has one row; each row's fate is known and its target resolves. */
export function checkWriterRetired(rows: readonly RetiredRow[], oldIds: readonly string[], trees: readonly GroupTree[]): WriterTreeFinding[] {
  const findings: WriterTreeFinding[] = [];
  const fail = (message: string) => { findings.push({ code: "RETIRED", group: "*", message }); };
  const kept = new Set(trees.flatMap(leavesOf));
  const old = new Set(oldIds);
  const copy = new Set(leavesOf(trees.find(tree => tree.group === "copy") ?? { nodes: [] } as unknown as GroupTree));
  const prose = new Set(leavesOf(trees.find(tree => tree.group === "prose") ?? { nodes: [] } as unknown as GroupTree));
  const rowsById = new Map<string, number>();
  for (const row of rows) rowsById.set(row.id, (rowsById.get(row.id) ?? 0) + 1);
  for (const id of oldIds) {
    if (kept.has(id)) continue;
    const count = rowsById.get(id) ?? 0;
    if (count !== 1) fail(`RETIRED: old id ${id} has ${count} retired rows`);
  }
  for (const row of rows) {
    if (!old.has(row.id)) fail(`RETIRED: ${row.id} is not an old Writer id`);
    if (kept.has(row.id)) fail(`RETIRED: ${row.id} is kept in the tree and also retired`);
    if (!(RETIRED_FATES as readonly string[]).includes(row.fate)) fail(`RETIRED: ${row.id} has unknown fate ${row.fate}`);
    if (typeof row.target !== "string" || !row.target.trim()) { fail(`RETIRED: ${row.id} has no target`); continue; }
    const parts = row.target.split(" + ");
    if (row.fate === "copy") {
      for (const part of parts) {
        const slot = part.split(":")[0]!;
        if (!copy.has(slot) && !/^page\.<id>\.meta$/.test(slot)) fail(`RETIRED: ${row.id} targets ${slot}, which is not a Copy leaf`);
      }
    } else if (row.fate === "prose") {
      if (!parts.every(part => prose.has(part))) fail(`RETIRED: ${row.id} targets ${row.target}, which is not a Prose leaf`);
    } else if (row.fate === "director-field") {
      if (!parts.every(part => DIRECTOR_FIELD.test(part))) fail(`RETIRED: ${row.id} targets ${row.target}, which is not a Director cell key`);
    } else if (row.fate === "purpose-shape") {
      if (!/^src\/contract\/copy-shapes\.json#[a-z-]+$/.test(row.target)) fail(`RETIRED: ${row.id} targets ${row.target}, not a copy-shapes entry`);
    }
  }
  return findings;
}
